import itertools
import json

def solve_puzzle():
    houses = [1, 2, 3, 4, 5]

    # Attributes
    names = ['Eric', 'Alice', 'Peter', 'Bob', 'Arnold']
    children = ['Timothy', 'Meredith', 'Samantha', 'Fred', 'Bella']

    solutions = []

    for names_perm in itertools.permutations(names):
        # Constraint 5: Eric is not in the third house.
        if names_perm[2] == 'Eric':
            continue
        # Constraint 6: Bob is not in the third house.
        if names_perm[2] == 'Bob':
            continue

        # Build children permutations respecting constraints 3 and 7 upfront
        # Constraint 3: Fred is in the second house (index 1)
        # Constraint 7: Fred is directly left of Bella -> Bella in third house (index 2)
        fixed_children = [None, 'Fred', 'Bella', None, None]
        remaining_positions = [i for i, v in enumerate(fixed_children) if v is None]
        remaining_children = [c for c in children if c not in {'Fred', 'Bella'}]

        for rem_perm in itertools.permutations(remaining_children):
            child_perm = fixed_children[:]
            for pos, val in zip(remaining_positions, rem_perm):
                child_perm[pos] = val

            pos_name = {name: idx for idx, name in enumerate(names_perm)}
            pos_child = {child: idx for idx, child in enumerate(child_perm)}

            # Constraint 2: Timothy is somewhere to the left of Samantha.
            if not (pos_child['Timothy'] < pos_child['Samantha']):
                continue

            # Constraint 1: Bob is somewhere to the left of the person's child named Samantha.
            if not (pos_name['Bob'] < pos_child['Samantha']):
                continue

            # Constraint 4: There is one house between Alice and Samantha.
            if abs(pos_name['Alice'] - pos_child['Samantha']) != 2:
                continue

            # Constraint 8: Samantha is somewhere to the left of Peter.
            if not (pos_child['Samantha'] < pos_name['Peter']):
                continue

            # Constraint 3 check (redundant due to fixing, but keep for safety)
            if pos_child['Fred'] != 1:
                continue

            # Constraint 7 check (redundant due to fixing, but keep for safety)
            if not (pos_child['Fred'] + 1 == pos_child['Bella']):
                continue

            solutions.append((names_perm, child_perm))

    if len(solutions) != 1:
        raise ValueError(f"Expected exactly one solution, found {len(solutions)}")

    names_sol, children_sol = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Child"],
            "rows": [
                [str(houses[i]), names_sol[i], children_sol[i]] for i in range(5)
            ]
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
